import unittest
from taf.ul.oam.selenium_coam.common.debug import catch_interface_exception, catch_intercepted_click_exception
from selenium.common.exceptions import ElementClickInterceptedException
import mock
from mock import patch
from pytest import raises


class TestFunctions(unittest.TestCase):

    @staticmethod
    def interface_func():
        pass

    def test_catch_interface_exception(self):
        self.assertEqual(catch_interface_exception(self.interface_func).__name__, "interface_func")

    def test_catch_intercepted_click_exception(self):
        self.assertEqual(catch_intercepted_click_exception(self.interface_func).__name__, "interface_func")

    def test_catch_intercepted_click_exception_does_not_raise_exception_when_everything_is_right(self):
        sleep_mock = mock.Mock(return_value=None)
        time_mock = mock.Mock()
        time_mock.sleep = sleep_mock

        @patch('taf.ul.oam.selenium_coam.common.debug.time', time_mock)
        @catch_intercepted_click_exception
        def do_everything_fine():
            return 'everything is fine, no need to panic or raise any suspicious exceptions'
        do_everything_fine()
        assert sleep_mock.call_count == 0

    def test_catch_intercepted_click_exception_raises_exception_when_we_cannot_ommit_problem(self):
        expected_exception = ElementClickInterceptedException
        expected_msg = "God damn it, I can't click!"

        sleep_mock = mock.Mock(return_value=None)
        time_mock = mock.Mock()
        time_mock.sleep = sleep_mock

        @patch('taf.ul.oam.selenium_coam.common.debug.time', time_mock)
        @catch_intercepted_click_exception
        def constantly_raise_exception():
            raise ElementClickInterceptedException("God damn it, I can't click!")

        with raises(expected_exception):
            constantly_raise_exception()
            assert expected_exception.message == expected_msg
        assert sleep_mock.call_count == 5

    def test_catch_intercepted_click_exception_works_fine_after_couple_exceptions_raised(self):
        sleep_mock = mock.Mock(return_value=None)
        time_mock = mock.Mock()
        time_mock.sleep = sleep_mock

        @patch('taf.ul.oam.selenium_coam.common.debug.time', time_mock)
        @catch_intercepted_click_exception
        def raise_exception_two_times_then_something_normal():
            raise_exception_two_times_then_something_normal.call_number += 1
            if raise_exception_two_times_then_something_normal.call_number in [1, 2]:
                raise ElementClickInterceptedException()
            if raise_exception_two_times_then_something_normal.call_number == 3:
                return True

        raise_exception_two_times_then_something_normal.call_number = 0

        raise_exception_two_times_then_something_normal()
        assert sleep_mock.call_count == 2
